import{_ as s,C as o,o as a,c as i,ag as r,E as n}from"./chunks/framework.CtWPcAmt.js";const f=JSON.parse('{"title":"Order Management","description":"","frontmatter":{},"headers":[],"relativePath":"orders/order-management.md","filePath":"orders/order-management.md","lastUpdated":1787558413000}'),l={name:"orders/order-management.md"};function d(h,e,p,g,c,m){const t=o("ImagePopup");return a(),i("div",null,[e[0]||(e[0]=r('<h1 id="order-management" tabindex="-1">Order Management <a class="header-anchor" href="#order-management" aria-label="Permalink to &quot;Order Management&quot;">​</a></h1><p>When a customer buys a seller&#39;s product, the order appears in the seller&#39;s <strong>Sales → Orders</strong>. From there the seller works their part of the order end to end — invoicing, shipping, and requesting payment — while the admin keeps oversight of the whole marketplace order.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>What the orders list tracks</li><li>How to process an order: invoice, ship, cancel</li><li>How a seller&#39;s earning and payment status flow</li></ul></div><h2 id="the-orders-list" tabindex="-1">The orders list <a class="header-anchor" href="#the-orders-list" aria-label="Permalink to &quot;The orders list&quot;">​</a></h2><p>Open <strong>Sales → Orders</strong>. Each row is an order containing this seller&#39;s items, with columns for the order <strong>ID / date / status / customer</strong>, <strong>items / payment / shipment</strong>, <strong>gross amount / discount / commission</strong>, and <strong>seller earning / seller payment status</strong>.</p>',5)),n(t,{src:"/images/order-management/orders-list.png",alt:"Seller orders list"}),e[1]||(e[1]=r('<p>The commission and seller-earning columns make it clear, per order, how much the marketplace keeps and how much you&#39;re owed (see <a href="/payments/commission-management">Commission Management</a>). Row actions surface exactly what an order needs next — <strong>Schedule Pickup</strong>, <strong>Print Label</strong>, <strong>Request Payment</strong>, <strong>Transaction</strong>, or <strong>View Order</strong> — each appearing only when it applies.</p><div class="info custom-block"><p class="custom-block-title">Sellers see only their own items</p><p>In a multi-seller order, each seller sees and processes only the items they sold, with money columns drawn from their own slice of the order. The admin sees the complete order across all sellers under <strong>Marketplace → Sales → Orders</strong>, where each row also names the <strong>seller</strong> and <strong>shop</strong> the items belong to, alongside the order&#39;s <strong>commission</strong> and the seller&#39;s <strong>earn</strong>.</p></div><h2 id="the-order-detail-page" tabindex="-1">The order detail page <a class="header-anchor" href="#the-order-detail-page" aria-label="Permalink to &quot;The order detail page&quot;">​</a></h2><p>Open an order with <strong>View Order</strong> to see everything about it — the items with their ordered / invoiced / shipped / refunded quantities, the totals (with the seller&#39;s earning and commission broken out), and the customer&#39;s addresses and chosen shipping and payment methods.</p>',4)),n(t,{src:"/images/order-management/order-view.png",alt:"Seller order detail"}),e[2]||(e[2]=r('<p>The header carries the fulfilment actions, each shown only when it&#39;s available and permitted:</p><ul><li><strong>Invoice</strong> — raise an invoice for your items (you can invoice partial quantities).</li><li><strong>Schedule Pickup / Shipment</strong> — ship the items through a <a href="/orders/fulfilment-carriers">fulfilment carrier</a>.</li><li><strong>Cancel</strong> — cancel the order (or your items in it) when it can&#39;t be fulfilled.</li></ul><p>As you invoice and ship, the <strong>Invoices</strong>, <strong>Shipments</strong>, and <strong>Refunds</strong> tabs fill in.</p><h2 id="shipping-an-order" tabindex="-1">Shipping an order <a class="header-anchor" href="#shipping-an-order" aria-label="Permalink to &quot;Shipping an order&quot;">​</a></h2><p>Selecting <strong>Schedule Pickup</strong> opens the shipment form. You enter the <strong>quantity to ship</strong> per inventory source, pick a <strong>Carrier</strong>, and choose the <strong>Product Ordered Source</strong>.</p>',5)),n(t,{src:"/images/order-management/shipment-create.png",alt:"Create shipment form"}),e[3]||(e[3]=r('<p>What you see next depends on the carrier:</p><ul><li><strong>Manual (Own Arrangement)</strong> — you arrange your own courier and simply type the <strong>Carrier Title</strong> and <strong>Tracking ID</strong>.</li><li><strong>Label-capable carriers</strong> — a <strong>Parcel</strong> section (weight and dimensions) appears; a shipping <strong>label</strong> is bought on submit, tracking is filled in automatically, and the shipment card shows a <strong>Download</strong> label button and the label cost.</li><li><strong>Pickup-capable carriers</strong> — a <strong>Collection</strong> section appears to book a courier pickup (either from published time slots or a ready/close window) with a pickup date and instructions.</li></ul><p>If a carrier can&#39;t be booked, the shipment is still saved and marked <strong>Not Booked</strong> so you can retry — nothing is lost. See <a href="/orders/fulfilment-carriers">Fulfilment Carriers</a> for how carriers are set up.</p><h2 id="getting-paid" tabindex="-1">Getting paid <a class="header-anchor" href="#getting-paid" aria-label="Permalink to &quot;Getting paid&quot;">​</a></h2><p>Once you&#39;ve fulfilled and invoiced an order, its <strong>seller payment status</strong> tracks whether you&#39;ve been paid. Use <strong>Request Payment</strong> on a completed order to ask the admin for your earnings — see <a href="/payments/payment-management">Payment Management</a>. Settled payouts show a <strong>Transaction</strong> link.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Invoice and ship promptly — a healthy fulfilment record feeds into <a href="/sellers/seller-account-health">Seller Account Health</a>, which the admin uses to keep the marketplace reliable.</p></div>',6))])}const _=s(l,[["render",d]]);export{f as __pageData,_ as default};
